+	private int counter = 0;
+
+	@Setup(Level.Iteration)
+	public void setup() throws Exception {
+		tempFile = Files.createTempFile("jfr-bench-string-", ".jfr");
+		OutputStream out = Files.newOutputStream(tempFile);
